// Row returns one SKU's row.
func (s *Store) Row(warehouse, sku string) (domain.StockRow, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if !s.has(warehouse) {
		return domain.StockRow{}, fmt.Errorf("%w: %s", domain.ErrUnknownWarehouse, warehouse)
	}
