// called with s.mu held.
func (s *Store) insertRow(warehouse string, i int, row domain.StockRow) {
	rows := append(s.rows[warehouse], domain.StockRow{})
	copy(rows[i+1:], rows[i:])
	rows[i] = row
	s.rows[warehouse] = rows
