	warehouse := r.PathValue("id")
	rows, err := s.store.Rows(warehouse)
	if err != nil {
		writeErr(w, err)
		return
	}
	report := domain.AvailabilityReport(rows, top)
	writeJSON(w, http.StatusOK, map[string]any{"warehouse": warehouse, "rows": report})
}

