// returns their names in execution order. Periodic jobs are rescheduled
// one interval out; a job that returned ErrBusy is retried after
// RetryDelay.
func (s *Scheduler) Tick() []string {
	now := s.clock.Now()
	var due, rest []entry
	for _, e := range s.queue {
		if e.due.After(now) {
			rest = append(rest, e)
		} else {
			due = append(due, e)
		}
