         * owns. parse_line rejects values that do not fit a slot, so the
         * existing storage is always large enough. The freelist is never
         * touched here -- which is what lets a completely full pool
         * still absorb value-only changes, and what keeps an unchanged
         * slot from being handed to a different key. */
        size_t len = strlen(val);
        memcpy(e->value, val, len + 1);
        return 0;
    }

    /* New key. First choice is to recycle an entry this reload is about
     * to drop, reusing its slot in place; that lets a full table be
     * turned over in place. Only if no stale entry is free do we append
     * a fresh one. */
    for (size_t i = 0; i < c->count; i++) {
        if (!c->entries[i].live) {
            size_t klen = strlen(key);
            size_t vlen = strlen(val);
            memcpy(c->entries[i].key, key, klen + 1);
            memcpy(c->entries[i].value, val, vlen + 1);
            c->entries[i].live = 1;
            return 0;
        }
    }
    return add_entry(c, key, val);
}

int cfg_reload(config *c, const char *text) {
    if (c == NULL || text == NULL)
        return -1;

    /* Mark every entry stale, but do NOT release its slot yet. Releasing
     * eagerly was the bug: an unchanged value kept pointing at a freed
     * slot, so a later pool_take for an unrelated key clobbered it (the
     * timeout_ms / metrics_addr cross-wire), the accounting drifted
     * because unchanged values were never re-taken, and the next reload
     * dropped those stale pointers a second time -- corrupting the
     * freelist and underflowing in_use until reloads failed outright. */
    for (size_t i = 0; i < c->count; i++)
        c->entries[i].live = 0;

    if (for_each_pair(c, text, reload_pair) != 0)
        return -1;

    /* Only now -- after the walk -- release the slots of keys the new
     * file omitted, and close the gaps they leave in the table. */
    size_t w = 0;
    for (size_t i = 0; i < c->count; i++) {
        if (c->entries[i].live)
            c->entries[w++] = c->entries[i];
        else
            pool_drop(c->pool, c->entries[i].value);
    }
    c->count = w;
    return 0;
}

/* --- queries ---------------------------------------------------------- */

const char *cfg_get(const config *c, const char *key) {
    if (c == NULL || key == NULL)
        return NULL;
    for (size_t i = 0; i < c->count; i++)
        if (strcmp(c->entries[i].key, key) == 0)
            return c->entries[i].value;
    return NULL;
}

size_t cfg_count(const config *c) {
    return c == NULL ? 0 : c->count;
}

