	var n int
	if err := Bind(&n, nil); err == nil {
		t.Fatal("Bind accepted a *int destination")
	}
	if err := Bind(baseCfg{}, nil); err == nil {
		t.Fatal("Bind accepted a non-pointer destination")
	}
}

