// Package wordfreq tallies word frequencies for the content-analytics
// service. Editors paste an article draft and get back vocabulary
// stats; the ingest job feeds whole documents through a Counter.
package wordfreq

import (
	"sort"
	"strings"
	"unicode"
)

// Counter accumulates word counts across one or more documents.
type Counter struct {
	counts    map[string]int
	total     int
	stopwords map[string]struct{}
}

// New returns an empty Counter.
func New() *Counter {
	return &Counter{counts: make(map[string]int)}
}

// Entry pairs a word with the number of times it has been seen.
type Entry struct {
	Word  string
	Count int
}

// SetStopwords defines the words excluded from TopK's report-time
// output. The raw tally (Count, Total, Distinct) is untouched, so the
// same Counter can still feed the vocabulary-size job. Matching is
// case-insensitive. Each call replaces the previous set outright;
// passing nil clears it.
func (c *Counter) SetStopwords(words []string) {
	if len(words) == 0 {
		c.stopwords = nil
		return
	}
	c.stopwords = make(map[string]struct{}, len(words))
	for _, w := range words {
		c.stopwords[strings.ToLower(w)] = struct{}{}
	}
}

// TopK returns the k most frequent words, most frequent first. Ties
// are broken alphabetically so the result is stable across runs
// regardless of map iteration order. k greater than the vocabulary
// size returns everything; k <= 0 returns nothing. Words set via
// SetStopwords are omitted from the result (the next-ranked words
// take their slots).
func (c *Counter) TopK(k int) []Entry {
	if k <= 0 {
		return nil
	}
	entries := make([]Entry, 0, len(c.counts))
	for word, count := range c.counts {
		if c.stopwords != nil {
			if _, skip := c.stopwords[word]; skip {
				continue
			}
		}
		entries = append(entries, Entry{Word: word, Count: count})
	}
	sort.Slice(entries, func(i, j int) bool {
		if entries[i].Count != entries[j].Count {
			return entries[i].Count > entries[j].Count
		}
		return entries[i].Word < entries[j].Word
	})
	if k > len(entries) {
		k = len(entries)
	}
	return entries[:k]
}

// Tokenize lowercases text and splits it into words. A word is a
// maximal run of letters and digits; apostrophes are kept when they
// sit inside a word ("don't" stays one word) but quoting apostrophes
// at the edges are stripped ("'fine'" tokenizes as "fine").
func Tokenize(text string) []string {
	isWordRune := func(r rune) bool {
		return unicode.IsLetter(r) || unicode.IsDigit(r) || r == '\''
	}
	var words []string
	for _, run := range strings.FieldsFunc(strings.ToLower(text), func(r rune) bool {
		return !isWordRune(r)
	}) {
		run = strings.Trim(run, "'")
		if run != "" {
			words = append(words, run)
		}
	}
	return words
}

// Add tokenizes text and adds every word to the tally.
func (c *Counter) Add(text string) {
	for _, w := range Tokenize(text) {
		c.counts[w]++
		c.total++
	}
}

// Count reports how many times word has been seen. Lookup is
// case-insensitive: Count("Go") and Count("go") agree.
func (c *Counter) Count(word string) int {
	return c.counts[strings.ToLower(word)]
}

// Distinct reports how many unique words have been seen.
func (c *Counter) Distinct() int { return len(c.counts) }

// Total reports how many words have been seen, repeats included.
func (c *Counter) Total() int { return c.total }

