int WaitList::sweep_holds(int now) {
    // Compact the queue in one stable forward pass. The old loop erased at
    // the current index and then incremented, so an element that slid into
    // a just-emptied slot was never re-examined (adjacent lapsed holds
    // survived), and erasing left every later entry in by_ticket_ pointing
    // one slot too high (desk lookups returned the wrong chart). Here each
    // surviving visit is moved to its final compacted slot and re-indexed.
    int dropped = 0;
    std::size_t write = 0;
    for (std::size_t read = 0; read < queue_.size(); read++) {
        if (queue_[read].hold_until <= now) {
            by_ticket_.erase(queue_[read].ticket);
            dropped++;
        } else {
            if (write != read) {
                queue_[write] = std::move(queue_[read]);
                by_ticket_[queue_[write].ticket] = write;
            }
            write++;
        }
    }
    queue_.resize(write);
    dropped_total_ += dropped;
    return dropped;
}

