  const calls: string[] = [];
  const fetchTile: FetchTile = async (key) => {
    calls.push(`${key.z}/${key.x}/${key.y}`);
    return `tile:${key.z}/${key.x}/${key.y}`;
  };
  return { calls, fetchTile };
