// isMoneyEvent reports whether an event is allowed to carry a non-zero amount.
func isMoneyEvent(ev Event) bool {
	return ev == EventPay || ev == EventRefund
}

// entryAmountOK enforces rule (e): money events must carry a positive amount,
// non-money events must carry zero.
func entryAmountOK(e Entry) error {
	if isMoneyEvent(e.Event) {
