// Package pool provides a fixed-size worker pool for CPU-bound transforms.
package pool

import "sync"

// Process applies fn to every item using the given number of workers and
// returns the results (order not guaranteed).
func Process(items []int, workers int, fn func(int) int) []int {
	if workers < 1 {
		workers = 1
	}

	jobs := make(chan int)
	results := make(chan int, len(items))

	// Add the workers before launching them so Wait can never observe a
	// zero counter prematurely.
	var wg sync.WaitGroup
	wg.Add(workers)
	for w := 0; w < workers; w++ {
		go func() {
			defer wg.Done()
			for item := range jobs {
				// Route results through a channel so the slice is only
				// ever touched by a single goroutine (no data race).
				results <- fn(item)
			}
		}()
	}

	// Feed all items in, then close jobs so the workers can stop ranging.
	for _, item := range items {
		jobs <- item
	}
	close(jobs)

	// Once every worker has drained jobs and exited, close results so the
	// collection loop below terminates.
	go func() {
		wg.Wait()
		close(results)
	}()

	out := make([]int, 0, len(items))
	for r := range results {
		out = append(out, r)
	}
	return out
}

