    CHECK_EQ_INT(lru_hits(&c), 0, "no hits yet");
    CHECK_EQ_INT(lru_misses(&c), 0, "no misses yet");
    CHECK_EQ_INT(lru_evictions(&c), 0, "no evictions yet");
