		`{"release": "r1", "services": []}`,
		`{"release": "r1", "services": [{"name": "api"}]}`,
		`{"release": "r1", "services": [{"name": "api", "image": "x"}, {"name": "api", "image": "y"}]}`,
	}
	for _, doc := range cases {
		if _, err := Load(strings.NewReader(doc)); err == nil {
			t.Fatalf("Load accepted invalid manifest %s", doc)
		}
	}
}

