// even if one is already sitting ready in the queue.
func Run(ctx context.Context, jobs <-chan Job, sink Sink) (int, error) {
	processed := 0
	for {
		// Re-check cancellation before pulling the next job. This gate runs
		// after the previous sink returned, so a cancel that arrived while we
