func TestDrainsQueueUntilClosed(t *testing.T) {
	jobs := make(chan Job, 8)
	for i := 1; i <= 5; i++ {
		jobs <- Job{ID: i, Payload: "row"}
	}
	close(jobs)
	var seen []int
	n, err := Run(context.Background(), jobs, func(j Job) { seen = append(seen, j.ID) })
	if err != nil {
		t.Fatalf("Run: %v", err)
	}
	if n != 5 || len(seen) != 5 {
		t.Fatalf("processed %d jobs (%v), want 5", n, seen)
	}
	for i, id := range seen {
		if id != i+1 {
			t.Fatalf("jobs out of order: %v", seen)
		}
	}
}

func TestEmptyClosedQueue(t *testing.T) {
	jobs := make(chan Job)
	close(jobs)
	n, err := Run(context.Background(), jobs, func(Job) {})
	if n != 0 || err != nil {
		t.Fatalf("Run = (%d, %v), want (0, nil)", n, err)
	}
}

func TestShutdownWhileQueueIsBusy(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	jobs := make(chan Job)
	stopProducer := make(chan struct{})
	defer close(stopProducer)
	go func() { // a tenant with a deep backlog: the queue never goes quiet
		id := 0
		for {
			select {
			case jobs <- Job{ID: id, Payload: "row"}:
				id++
			case <-stopProducer:
				return
			}
		}
	}()

	handled := make(chan Job, 4096)
	type result struct {
		n   int
		err error
	}
	done := make(chan result, 1)
	go func() {
		n, err := Run(ctx, jobs, func(j Job) { handled <- j })
		done <- result{n, err}
	}()

	for i := 0; i < 3; i++ { // consumer is demonstrably up and working
		<-handled
	}
	cancel()

	select {
	case r := <-done:
		if !errors.Is(r.err, context.Canceled) {
			t.Fatalf("Run returned err = %v, want context.Canceled", r.err)
		}
		if r.n < 3 {
			t.Fatalf("Run reported %d processed jobs, want at least 3", r.n)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("shutdown requested but Run kept consuming the queue")
	}
}

func TestCancelDuringSinkNeverTakesAnotherBufferedJob(t *testing.T) {
	// Repeating the synchronized scenario catches implementations that put a
	// ready jobs receive and a ready ctx.Done in the same select. Such a select
	// may choose the next job even though shutdown was requested while the
	// current sink was still finishing.
	for attempt := 0; attempt < 64; attempt++ {
		ctx, cancel := context.WithCancel(context.Background())
		jobs := make(chan Job, 2)
		jobs <- Job{ID: 1}
		jobs <- Job{ID: 2}

		entered := make(chan struct{})
		release := make(chan struct{})
		done := make(chan struct {
			n   int
			err error
		}, 1)
		calls := 0
		go func() {
			n, err := Run(ctx, jobs, func(Job) {
				calls++
				if calls == 1 {
					close(entered)
					<-release
				}
			})
			done <- struct {
				n   int
				err error
			}{n, err}
		}()

		<-entered
		cancel()
		close(release)
		got := <-done
		if !errors.Is(got.err, context.Canceled) {
			t.Fatalf("attempt %d: Run err = %v, want context.Canceled", attempt, got.err)
		}
		if got.n != 1 {
			t.Fatalf("attempt %d: processed %d jobs after cancel during the first sink, want exactly 1", attempt, got.n)
		}
	}
}

