// Package consumer drains the export queue and hands each job to a sink.
// One consumer runs per tenant inside the exporter process; the process
// manager cancels their contexts when it wants a clean shutdown, then
// waits for every Run to return before exiting.
package consumer

import "context"

// Job is one export request pulled off the tenant's queue.
type Job struct {
	ID      int
	Payload string
}

// Sink receives completed jobs (writes rows, uploads files, etc.).
type Sink func(Job)

// Run processes jobs from the queue until the queue is closed (returns
// nil) or ctx is cancelled (returns ctx.Err()). It reports how many jobs
// were handed to the sink.
//
// Shutdown contract: once ctx is cancelled, Run finishes the job currently
// in hand and then returns. It never starts a new job after cancellation,
// even if one is already sitting ready in the queue.
func Run(ctx context.Context, jobs <-chan Job, sink Sink) (int, error) {
	processed := 0
	for {
		// Re-check cancellation before pulling the next job. This gate runs
		// after the previous sink returned, so a cancel that arrived while we
		// were busy is honoured here instead of being beaten by a ready job
		// inside the select below.
		if err := ctx.Err(); err != nil {
			return processed, err
		}
		select {
		case job, ok := <-jobs:
			if !ok {
				// Queue drained and closed: clean exit.
				return processed, nil
			}
			sink(job)
			processed++
		case <-ctx.Done():
			// Idle on an open, empty queue when shutdown was requested.
			return processed, ctx.Err()
		}
	}
}

