  assert.equal(c.r, 128);
  assert.equal(c.g, 0);
  assert.equal(c.b, 255);
  near(c.a, 128 / 255, 0.001, 'alpha');
  assert.equal(parseHex('#000000ff').a, 1);
  assert.equal(parseHex('#00000000').a, 0);
});

