    let src = "# edge tier\n\n[server]\nhost = edge-1.prod.internal\nport = 8443\ntls = true\nworkers = 32\nlog_level = warn\nallow = 10.0.0.0/8, fe80::/10\n\n[limits]\nrps = 400\n";
