    ExprPtr expr = bin("*", ref("qty"), lit(3L));
    Env a = kiosk();
    Env b = kiosk();
    b["qty"] = Value(2L);
    CHECK_EVAL(expr, a, "long:36");
    CHECK_EVAL(expr, b, "long:6");
    CHECK_EVAL(expr, a, "long:36");
    Env c;
    CHECK_EVAL(expr, c, "err:undef(qty)");
}

