// tabskit — the docs site's disclosure widgets: compound Tabs and Accordion
// components wired together through context. Rendering is a pure function of
// props, so the same components serve the static build and the client.

import {
  Children,
  cloneElement,
  createContext,
  isValidElement,
  useContext,
  useState,
} from "react";
import type { ReactNode } from "react";

/** Clone direct children with their positional index injected. */
function withIndex(children: ReactNode): ReactNode {
  return Children.map(children, (child, index) =>
    isValidElement<{ index?: number }>(child) ? cloneElement(child, { index }) : child,
  );
}

// ---------------------------------------------------------------- Tabs

interface TabsContextValue {
  active: number;
  id: string;
}

const TabsContext = createContext<TabsContextValue>({ active: 0, id: "tabs" });

interface TabsProps {
  children?: ReactNode;
  defaultIndex?: number;
  index?: number;
  id?: string;
}

export function Tabs({ children, defaultIndex = 0, index, id = "tabs" }: TabsProps) {
  const [stateActive] = useState(defaultIndex);
  // Controlled when `index` is provided (0 included); otherwise seed from
  // defaultIndex exactly as before.
  const active = index !== undefined ? index : stateActive;
  return (
    <div className="tabs">
      <TabsContext.Provider value={{ active, id }}>{children}</TabsContext.Provider>
    </div>
  );
}

interface TabListProps {
  children?: ReactNode;
  label?: string;
}

export function TabList({ children, label }: TabListProps) {
  return (
    <div className="tab-list" role="tablist" {...(label ? { "aria-label": label } : {})}>
      {withIndex(children)}
    </div>
  );
}

interface TabProps {
  children?: ReactNode;
  index?: number;
}

export function Tab({ children, index = 0 }: TabProps) {
  const { active, id } = useContext(TabsContext);
  const isActive = index === active;
  return (
    <button
...[TRUNCATED 52 CHARS]...
{index !== active || undefined}
      role="tabpanel"
      id={`${id}-panel-${index}`}
      aria-labelledby={`${id}-tab-${index}`}
