import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.TreeMap;

/**
 * Renders the month-end statement file for a plaza feed.
 *
 * Layout (one statement block per account, accounts in sorted order;
 * within a block the crossings appear in feed order):
 *
 *   ACCOUNT TP-00104
 *     PLZ-030 day 2 $0.95
 *   SUBTOTAL TP-00104 trips 1 $0.95
 *   ...
 *   TOTAL $12.95
 *
 * The archive stores a checksum of every statement file, so the output
 * bytes are contract: same feed in, same bytes out, forever.
 */
public final class StatementReport {

    private StatementReport() {}

    public static String money(long cents) {
        return String.format(Locale.ROOT, "$%d.%02d", cents / 100, cents % 100);
    }

    public static String generate(List<Crossing> crossings) {
        // Group every crossing under its account in a single pass. A TreeMap
        // iterates accounts in sorted order; each per-account list keeps the
        // crossings in feed (insertion) order. This replaces the old
        // O(accounts x crossings) repeated full scans.
        TreeMap<String, ArrayList<Crossing>> byAccount = new TreeMap<>();
        for (Crossing c : crossings) {
            byAccount.computeIfAbsent(c.account(), a -> new ArrayList<>()).add(c);
        }

        // Pre-size generously so we never copy the whole buffer. Amortized
        // O(n) appends replace the old O(n^2) String concatenation.
        StringBuilder out = new StringBuilder(crossings.size() * 32 + 64);
        long grandTotal = 0;
        for (var entry : byAccount.entrySet()) {
            String account = entry.getKey();
            out.append("ACCOUNT ").append(account).append('\n');
            long subtotal = 0;
            int trips = 0;
            for (Crossing c : entry.getValue()) {
                out.append("  ").append(c.plaza()).append(" day ")
                        .append(c.day()).append(' ').append(money(c.cents())).append('\n');
                subtotal += c.cents();
                trips++;
            }
            out.append("SUBTOTAL ").append(account).append(" trips ")
                    .append(trips).append(' ').append(money(subtotal)).append('\n');
            grandTotal += subtotal;
        }
        out.append("TOTAL ").append(money(grandTotal)).append('\n');
        return out.toString();
    }
}

