export type StitchOpts = { onProbe?: (id: string) => void };

type OpenRec = { id: string; ts: number; method: string; used: boolean };

export function stitch(entries: Entry[], opts: StitchOpts = {}): StitchResult {
  const probe = opts.onProbe ?? (() => {});
  const opens: OpenRec[] = [];
  // Per-id stack of still-unconsumed opens (top = most recent), so a close
  // resolves its matching open in O(1) instead of rescanning the whole log.
  // Same-id opens nest like a stack, which is exactly the contract.
  const byId = new Map<string, OpenRec[]>();
  const calls: Call[] = [];
  const orphanCloses: string[] = [];

  for (const e of entries) {
    if (e.kind === 'open') {
      const rec: OpenRec = { id: e.id, ts: e.ts, method: e.method, used: false };
      opens.push(rec);
      let stack = byId.get(e.id);
      if (!stack) {
        stack = [];
        byId.set(e.id, stack);
      }
      stack.push(rec);
      continue;
    }
    // Most recent unconsumed open with this id: top of its stack.
    const stack = byId.get(e.id);
    const rec = stack && stack.length ? stack.pop()! : undefined;
    if (!rec) {
      orphanCloses.push(e.id);
      continue;
    }
    probe(rec.id);
    rec.used = true;
    calls.push({
      id: e.id,
      method: rec.method,
      openTs: rec.ts,
      closeTs: e.ts,
      durationMs: e.ts - rec.ts,
      status: e.status,
    });
  }

  const unmatchedOpens = opens.filter((o) => !o.used).map((o) => o.id);
  return { calls, unmatchedOpens, orphanCloses };
}

