func TestConcurrentPutsAllSurviveReopen(t *testing.T) {
	dir := t.TempDir()
	st := openStore(t, dir)

	const writers, perWriter = 8, 50
	var wg sync.WaitGroup
	for w := 0; w < writers; w++ {
