		}
	}
}

func TestOtherTopicsDoNotLeakIn(t *testing.T) {
	b := NewBus()
	sub, err := b.Subscribe("jobs", 4)
	if err != nil {
		t.Fatalf("Subscribe: %v", err)
	}
	b.Publish("jobs.retry", "not for the exact-topic sub")
	b.Publish("metrics", "also not")
