	b.Publish("jobs", "yes")
	if m := recv(t, sub); m.Payload != "yes" {
		t.Fatalf("got %+v, want payload yes", m)
	}
}

func TestDeliveryOrderIsPublishOrder(t *testing.T) {
	b := NewBus()
	sub, err := b.Subscribe("audit", 8)
	if err != nil {
		t.Fatalf("Subscribe: %v", err)
	}
	for i := 0; i < 5; i++ {
		b.Publish("audit", fmt.Sprintf("event-%d", i))
	}
	for i := 0; i < 5; i++ {
