/** A schedule hook the test controls by hand. */
function manualSchedule() {
  const queued: Array<() => void> = [];
  return {
    queued,
    schedule: (flush: () => void) => {
      queued.push(flush);
    },
    runAll() {
      while (queued.length > 0) queued.shift()!();
    },
  };
}

