func applyBounded(t *testing.T, l *Ledger, txns []Txn) (int, error) {
	t.Helper()
	type result struct {
		n   int
		err error
	}
	ch := make(chan result, 1)
	go func() {
		n, err := l.ApplyBatch(txns)
		ch <- result{n, err}
	}()
	select {
	case r := <-ch:
		return r.n, r.err
	case <-time.After(2 * time.Second):
		t.Fatal("ApplyBatch did not return in time")
		return 0, nil
	}
}

